package org.slavicmyths.verify.client;
import java.nio.file.*;import java.util.*;import java.util.concurrent.atomic.AtomicBoolean;
import net.minecraft.client.Minecraft;import net.minecraft.core.*;import net.minecraft.world.*;import net.minecraft.world.entity.item.ItemEntity;import net.minecraft.world.item.*;import net.minecraft.world.level.*;import net.minecraft.world.level.block.*;import net.minecraft.world.phys.*;import org.slavicmyths.brewing.*;import org.slavicmyths.progression.Knowledge;
/** Real production aging ticks; no assignment to fermentation age or game-time acceleration. Combat is outside this fixture. */
public final class Brew269 {
 static final String MODE=System.getProperty("slavicmyths.qa269.brewMode","initial");static final Path OUT=Path.of("../../docs/implementation/stabilization269-brewing-20261026");
 static final BlockPos A=new BlockPos(1000,201,10),B=new BlockPos(1004,201,10),PRESS=new BlockPos(1000,201,6),KEG=new BlockPos(1004,201,6);
 static final List<Map<String,Object>> checks=new ArrayList<>();static final Map<String,Object> out=new LinkedHashMap<>();static final AtomicBoolean queued=new AtomicBoolean();static final Set<String> shots=new HashSet<>();
 static final String[] INITIAL={"blocked","beerStart","kvassStart","wrong","youngBeer","youngKvass","pressLoad","press1","press2","press3","juice","pomace"};
 static final String[] LONG={"readyBeer","pitcher","readyKvass","kegInsert","kegReject","kegPitcher","kegDraw","agedBeer","agedKvass","spoiledKvass","breakBeer"};
 static boolean done,started,prepared;static int phase=-1,seen=-1;static long born=System.nanoTime(),lastTick=Long.MIN_VALUE,target,lastHeartbeat;static volatile int action=-1;static volatile BlockPos click;static BrewTile beer,kvass,press,keg;static int spoilBefore;
 static String[] steps(){return MODE.equals("initial")?INITIAL:LONG;}static Item item(String s){return Brewing.item(s);}
 static void check(boolean ok,String name){checks.add(Map.of("status",ok?"PASS":"FAIL","test",name));System.out.println("QA269_BREW "+(ok?"PASS ":"FAIL ")+name);if(!ok)throw new IllegalStateException(name);}
 static void finish(Throwable e){if(done)return;done=true;try{Files.createDirectories(OUT);out.put("status",e==null?"PASS_SINGLE_CLIENT_BREW_SCOPE":"FAIL");out.put("checks",checks);out.put("error",e==null?null:e.toString());out.put("scope","one actual client, supplied fixtures/batches, native useItemOn packets and unaccelerated block ticks; Survival acquisition/MP NOT_RUN");if(beer!=null){out.put("final_beer_age",beer.fermentation.age);out.put("final_kvass_age",kvass.fermentation.age);out.put("final_beer_servings",beer.fermentation.servings);out.put("final_kvass_servings",kvass.fermentation.servings);}Files.writeString(OUT.resolve(MODE+"-receipt.json"),new com.google.gson.GsonBuilder().setPrettyPrinting().create().toJson(out));if(e!=null)e.printStackTrace();}catch(Exception ex){ex.printStackTrace();}Minecraft.getInstance().stop();}
 static void stash(net.minecraft.server.level.ServerPlayer p,ItemStack stack){if(stack.isEmpty())return;for(int i=1;i<36;i++){var slot=p.getInventory().getItem(i);if(ItemStack.isSameItemSameComponents(slot,stack)&&slot.getCount()+stack.getCount()<=slot.getMaxStackSize()){slot.grow(stack.getCount());return;}}for(int i=1;i<36;i++)if(p.getInventory().getItem(i).isEmpty()){p.getInventory().setItem(i,stack.copy());return;}throw new IllegalStateException("QA fixture inventory full");}
 static void hand(net.minecraft.server.level.ServerPlayer p,ItemStack stack){var old=p.getMainHandItem().copy();if(ItemStack.isSameItemSameComponents(old,stack)&&old.getCount()==stack.getCount())return;p.setItemInHand(InteractionHand.MAIN_HAND,stack);stash(p,old);p.closeContainer();p.inventoryMenu.broadcastChanges();}
 static void existing(net.minecraft.server.level.ServerPlayer p,String beverage,String quality){if(matches(p.getMainHandItem(),beverage,quality))return;for(int i=1;i<36;i++){var stack=p.getInventory().getItem(i);if(matches(stack,beverage,quality)){var copy=stack.copyWithCount(1);stack.shrink(1);hand(p,copy);return;}}throw new IllegalStateException("expected real sample missing "+beverage+"/"+quality);}
 static boolean matches(ItemStack s,String b,String q){return !s.isEmpty()&&s.getItem() instanceof BeverageItem&&BeverageItem.beverage(s).equals(b)&&BeverageItem.quality(s).equals(q);}
 static int samples(net.minecraft.server.level.ServerPlayer p,String b,String q){int n=0;for(int i=0;i<p.getInventory().getContainerSize();i++){var stack=p.getInventory().getItem(i);if(matches(stack,b,q))n+=stack.getCount()*BeverageItem.data(stack).getInt("Servings");}return n;}
 static int containerSamples(net.minecraft.server.level.ServerPlayer p,String b,String q,String container){int n=0;for(int i=0;i<p.getInventory().getContainerSize();i++){var stack=p.getInventory().getItem(i);if(matches(stack,b,q)&&BeverageItem.data(stack).getString("Container").equals(container))n+=stack.getCount()*BeverageItem.data(stack).getInt("Servings");}return n;}
 static BrewTile place(net.minecraft.server.level.ServerLevel w,BlockPos at,String kind){w.setBlock(at,Blocks.AIR.defaultBlockState(),3);w.setBlock(at,Brewing.BLOCKS.get(kind).get().defaultBlockState(),3);return (BrewTile)w.getBlockEntity(at);}
 static void setup(Minecraft mc){var s=mc.getSingleplayerServer();var w=s.overworld();var p=s.getPlayerList().getPlayers().getFirst();p.stopRiding();p.setNoGravity(true);p.setInvulnerable(true);p.setGameMode(GameType.SURVIVAL);p.teleportTo(w,1002.5,201,8.5,180,0);w.setChunkForced(62,0,true);w.getChunkAt(A);out.put("player_uuid",p.getUUID().toString());try(var data=BrewTile.class.getResourceAsStream("BrewTile.class")){out.put("production_brew_class_sha256",java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(data.readAllBytes())));}catch(Exception e){throw new RuntimeException(e);}check(p.getGameProfile().getName().equals("QA269Brewer"),"distinct actual brewing test profile");check(org.slavicmyths.tales.TaleData.get(w).compatible(),"journey data compatible");if(MODE.equals("restart")){kvass=(BrewTile)w.getBlockEntity(B);keg=(BrewTile)w.getBlockEntity(KEG);check(w.getBlockEntity(A)==null&&w.getBlockState(A).isAir(),"destroyed beer vat stays absent after actual process restart");check(kvass!=null&&!kvass.fermentation.active()&&kvass.fermentation.servings==0,"exhausted kvass vat stays empty after actual process restart");check(keg!=null&&keg.servings==0,"drained keg stays empty after actual process restart");check(Knowledge.knows(p,"self_brewed_beer"),"existing beer journey persists after actual process restart");check(samples(p,"light_beer","young")==1&&samples(p,"light_beer","ready")==3&&containerSamples(p,"light_beer","ready","dark_bottle")==1&&containerSamples(p,"light_beer","ready","wooden_mug")==2&&samples(p,"light_beer","aged")==1,"three new beer samples and two distinct pre-existing cleanup drops persist exactly");check(samples(p,"kvass","young")==1&&samples(p,"kvass","ready")==5&&samples(p,"kvass","aged")==1,"all seven poured kvass portions persist without duplication");check(spoiled(p)==6,"six total spoiled portions persist across actual process restart");finish(null);return;}check(!Knowledge.knows(p,"self_brewed_beer"),"fresh player lacks self_brewed_beer before actual completion");
  if(MODE.equals("initial")){p.getInventory().clearContent();for(int x=998;x<=1006;x++)for(int z=4;z<=12;z++)w.setBlock(new BlockPos(x,200,z),Blocks.STONE.defaultBlockState(),2);beer=place(w,A,"fermentation_vat");kvass=place(w,B,"fermentation_vat");press=place(w,PRESS,"fruit_press");keg=place(w,KEG,"small_keg");beer.setItem(0,new ItemStack(Items.DIRT));}
  else{beer=(BrewTile)w.getBlockEntity(A);kvass=(BrewTile)w.getBlockEntity(B);press=(BrewTile)w.getBlockEntity(PRESS);keg=(BrewTile)w.getBlockEntity(KEG);check(beer!=null&&kvass!=null&&beer.fermentation.active()&&kvass.fermentation.active(),"physical batches survive new client/server process");check(beer.fermentation.servings==7&&kvass.fermentation.servings==7,"previous young samples remain deducted after restart");check(beer.fermentation.age>0&&(MODE.equals("baseline2")||beer.fermentation.age<2400),"batch age survives offline interval (young required except diagnostic baseline2)");check(samples(p,"light_beer","young")==1&&samples(p,"kvass","young")==1,"young sample metadata persisted in actual player inventory");out.put("loaded_beer_age",beer.fermentation.age);out.put("loaded_kvass_age",kvass.fermentation.age);}
  prepared=true;
 }
 static int minAge(String name){return name.startsWith("aged")?8400:name.startsWith("spoiled")||name.equals("breakBeer")?12000:MODE.equals("initial")?0:2400;}
 static void request(Minecraft mc,String n){var p=mc.getSingleplayerServer().getPlayerList().getPlayers().getFirst();p.closeContainer();p.teleportTo(p.serverLevel(),1002.5,201,8.5,180,0);p.setDeltaMovement(Vec3.ZERO);click=A;ItemStack held=ItemStack.EMPTY;
  switch(n){case "blocked","beerStart"->held=new ItemStack(item("light_beer_wort"));case "kvassStart"->{click=B;held=new ItemStack(item("kvass_wort"));}case "wrong"->held=new ItemStack(Items.DIRT);case "youngBeer","readyBeer","agedBeer"->held=new ItemStack(item(n.equals("readyBeer")?"dark_bottle":"wooden_mug"));case "youngKvass","readyKvass","agedKvass"->{click=B;held=new ItemStack(item("wooden_mug"));}case "pitcher"->{click=B;held=new ItemStack(item("ceramic_pitcher"));}case "spoiledKvass"->{click=B;held=new ItemStack(item("dark_bottle"));}case "pressLoad"->{click=PRESS;held=new ItemStack(Items.APPLE,4);}case "press1","press2","press3","juice","pomace"->click=PRESS;case "kegInsert"->{existing(p,"kvass","ready");click=KEG;return;}case "kegReject"->{existing(p,"kvass","young");click=KEG;return;}case "kegPitcher"->{click=KEG;held=new ItemStack(item("ceramic_pitcher"));}case "kegDraw"->{click=KEG;held=new ItemStack(item("wooden_mug"));}}
  hand(p,held);
 }
 static void validate(Minecraft mc,String n){var s=mc.getSingleplayerServer();var p=s.getPlayerList().getPlayers().getFirst();var a=beer.fermentation;var b=kvass.fermentation;out.put(n+"_age",a.age);out.put(n+"_server_position",p.position().toString());out.put(n+"_held",p.getMainHandItem().toString());out.put(n+"_ready_beer_samples",samples(p,"light_beer","ready"));
  switch(n){case "blocked"->{check(!a.active()&&p.getMainHandItem().is(item("light_beer_wort")),"occupied vat rejects batch without consumption");beer.clearContent();}
   case "beerStart"->{check(a.active()&&a.servings==8&&a.age>0&&a.age<2400,"real beer batch starts eight portions at young age");check(p.getInventory().countItem(item("light_beer_wort"))==0,"one real wort item consumed");}
   case "kvassStart"->check(b.active()&&b.servings==8&&b.beverage.equals("kvass"),"second physical vat starts real kvass batch");
   case "wrong"->{check(a.servings==8&&p.getMainHandItem().is(Items.DIRT),"wrong vessel cannot extract fermentation");check(!beer.canPlaceItem(0,new ItemStack(Items.APPLE)),"active fermentation denies ingredient insertion");}
   case "youngBeer"->check(a.servings==7&&samples(p,"light_beer","young")==1,"young beer pour consumes one serving with young metadata");
   case "youngKvass"->check(b.servings==7&&samples(p,"kvass","young")==1,"young kvass pour consumes one serving with young metadata");
   case "pressLoad"->check(press.items.get(0).is(Items.APPLE)&&press.items.get(0).getCount()==4,"real press interaction loads four apples");
   case "press1","press2"->check(press.pressActions==(n.equals("press1")?1:2)&&press.items.get(1).isEmpty(),"no premature juice "+n);
   case "press3"->check(press.items.get(0).isEmpty()&&press.items.get(1).is(item("apple_juice_bottle"))&&press.items.get(2).is(item("fruit_pomace")),"three native press actions produce one juice and one pomace");
   case "juice"->check(press.items.get(1).isEmpty()&&p.getInventory().countItem(item("apple_juice_bottle"))==1,"real press interaction retrieves juice once");
   case "pomace"->check(press.items.get(2).isEmpty()&&p.getInventory().countItem(item("fruit_pomace"))==1,"real press interaction retrieves pomace once");
   case "readyBeer"->{check(BrewRules.quality(a.age).equals("ready")&&samples(p,"light_beer","ready")==1&&a.servings==6,"unaccelerated age2400 produces ready beer in dark bottle");check(Knowledge.knows(p,"self_brewed_beer"),"vat completion awards existing self_brewed_beer journey");}
   case "pitcher"->check(b.servings==3&&samples(p,"kvass","ready")==4,"ready pitcher stores four portions and deducts four");
   case "readyKvass"->check(b.servings==2&&samples(p,"kvass","ready")==5,"ready kvass mug deducts one additional portion");
   case "kegInsert"->check(keg.servings==1&&keg.beverage.equals("kvass")&&keg.quality.equals("ready"),"real ready sample transfers into keg with quality");
   case "kegReject"->check(keg.servings==1&&samples(p,"kvass","young")==1,"keg rejects different quality without consuming young sample");
   case "kegPitcher"->check(keg.servings==1&&p.getMainHandItem().is(item("ceramic_pitcher")),"keg under four portions does not consume pitcher");
   case "kegDraw"->check(keg.servings==0&&keg.beverage.isEmpty()&&samples(p,"kvass","ready")==5,"keg round trip preserves exact five ready sample portions");
   case "agedBeer"->check(a.servings==5&&samples(p,"light_beer","aged")==1,"unaccelerated age8400 produces aged beer");
   case "agedKvass"->check(b.servings==1&&samples(p,"kvass","aged")==1,"unaccelerated age8400 produces aged kvass");
   case "spoiledKvass"->check(b.servings==0&&b.beverage.isEmpty()&&samples(p,"spoiled_brew","spoiled")==1,"native age12000 pour exhausts vat as spoiled brew");
  }
 }
 static int spoiled(net.minecraft.server.level.ServerPlayer p){return p.getInventory().countItem(item("spoiled_brew"))+p.serverLevel().getEntitiesOfClass(ItemEntity.class,new AABB(A).inflate(8)).stream().filter(e->e.getItem().is(item("spoiled_brew"))).mapToInt(e->e.getItem().getCount()).sum();}
 static void server(Minecraft mc){try{var s=mc.getSingleplayerServer();long now=s.overworld().getGameTime();if(now==lastTick)return;lastTick=now;if(!prepared){setup(mc);return;}if(phase>=steps().length){finish(null);return;}
  if(phase<0){phase=0;target=0;}String n=steps()[phase];if(target==0){if(Math.min(beer.fermentation.age,kvass.fermentation.age)<minAge(n)){if(now%100==0){var actor=s.getPlayerList().getPlayers().getFirst();actor.teleportTo(s.overworld(),1002.5,201,8.5,180,0);actor.setDeltaMovement(Vec3.ZERO);}if(now-lastHeartbeat>=1200){lastHeartbeat=now;System.out.println("QA269_BREW_AGE "+beer.fermentation.age+"/12000 stage="+n);try{Files.createDirectories(OUT);Files.writeString(OUT.resolve("live-progress.json"),new com.google.gson.Gson().toJson(Map.of("mode",MODE,"stage",n,"beer_age",beer.fermentation.age,"kvass_age",kvass.fermentation.age,"game_time",now)));}catch(Exception error){throw new RuntimeException(error);}}return;}
   if(n.equals("breakBeer")){var p=s.getPlayerList().getPlayers().getFirst();out.put("beer_age_before_native_break",beer.fermentation.age);spoilBefore=spoiled(p);check(beer.fermentation.servings==5,"five beer servings remain before native destruction");check(p.gameMode.destroyBlock(A),"native player destruction removes spoiled vessel");check(beer.fermentation.servings==0&&spoiled(p)==spoilBefore+5,"native break preserves all five remaining servings exactly once");p.gameMode.destroyBlock(A);check(spoiled(p)==spoilBefore+5,"repeat destruction cannot duplicate spoiled drops");phase++;return;}
   request(mc,n);target=now+20;action=phase;return;}
  if(now<target+20)return;validate(mc,n);phase++;target=0;if(MODE.equals("initial")&&phase==steps().length){out.put("saved_beer_age",beer.fermentation.age);out.put("saved_kvass_age",kvass.fermentation.age);mc.execute(()->finish(null));}
 }catch(Throwable e){mc.execute(()->finish(e));}finally{queued.set(false);}}
 public static void tick(Minecraft mc){if(done||mc.player==null||mc.getSingleplayerServer()==null)return;try{if(!started){started=true;out.put("master_volume",mc.options.getSoundSourceOptionInstance(net.minecraft.sounds.SoundSource.MASTER).get());out.put("fps_limit",mc.options.framerateLimit().get());out.put("available_processors",Runtime.getRuntime().availableProcessors());out.put("max_heap_bytes",Runtime.getRuntime().maxMemory());out.put("GLFW_visible",org.lwjgl.glfw.GLFW.glfwGetWindowAttrib(mc.getWindow().getWindow(),org.lwjgl.glfw.GLFW.GLFW_VISIBLE));}
  if(System.nanoTime()-born>(MODE.equals("fixed")?950L:240L)*1_000_000_000L)throw new IllegalStateException("brew timeout phase="+phase);if(queued.compareAndSet(false,true))mc.getSingleplayerServer().execute(()->server(mc));if(action>seen&&mc.level.getGameTime()>=target){seen=action;out.put("sent_phase_"+action+"_client_position",mc.player.position().toString());System.out.println("QA269_BREW_SENT phase="+action+" position="+mc.player.position());mc.player.getInventory().selected=0;mc.gameMode.useItemOn(mc.player,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(click),Direction.UP,click,false));}
 }catch(Throwable e){finish(e);}}
 public static void capture(Minecraft mc){if(done||!started||phase<0||!shots.add(MODE+phase))return;try{Files.createDirectories(OUT);try(var image=net.minecraft.client.Screenshot.takeScreenshot(mc.getMainRenderTarget())){image.writeToFile(OUT.resolve(MODE+"-phase"+phase+".png"));}}catch(Exception e){finish(e);}}
}
